template.query:
query SearchTodos($tableId: ID, $searchTerm: String) {
        nodes: nodes(
          filter: {
            tableId: $tableId
            search: $searchTerm
          }
          pagination: { limit: 20, offset: 0 }
        ) {
          nodes {
            id
            content
            createdAt
            updatedAt
            attributes {
              id
              value
              attribute {
                id
                identifier
                dataType
              }
            }
          }
          totalCount
          hasNextPage
        }
      }
